from itertools import combinations_with_replacement
from math import comb


def nonempty_subset_sums(sequence, modulus):
    return {
        sum(sequence[i] for i in range(len(sequence)) if mask & (1 << i)) % modulus
        for mask in range(1, 1 << len(sequence))
    }


def main():
    forbidden = frozenset({0, 4, 12})
    checked = 0

    # Sorting does not change the set of indexed subset sums.
    # This enumeration includes repetitions and zero entries.
    for sequence in combinations_with_replacement(range(16), 5):
        sums = nonempty_subset_sums(sequence, 16)
        assert sums & forbidden, (sequence, sorted(sums))
        checked += 1
    assert checked == comb(20, 5) == 15504

    N = 80
    d = 5
    assert N % d == 0
    assert N % 16 == 0
    A = {a for a in range(N) if a % 16 not in forbidden}
    B = set(range(N)) - A
    assert len(A) == 65
    assert len(B) == 15
    assert d * len(A) > (d - 1) * N

    # Verify the fiber sizes and the reduction homomorphism used to lift
    # the exhaustive obstruction from Z_16 to every multiset in Z_80.
    for residue in range(16):
        assert sum(1 for a in range(N) if a % 16 == residue) == 5
    for x in range(N):
        for y in range(N):
            assert ((x + y) % N) % 16 == (x % 16 + y % 16) % 16

    print({
        'checked_size_five_multisets_modulo_16': checked,
        'N': N,
        'd': d,
        'A_size': len(A),
        'proposed_bound': (d - 1) * N // d,
    })


if __name__ == '__main__':
    main()
